{
  "findings": [
    {
      "check_id": "CKV_AWS_12",
      "title": "Ensure all EBS volumes are encrypted",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The first ebs_block_device block does not explicitly set 'encrypted = true'. While it references a snapshot, relying on implicit encryption or unencrypted snapshots is a security risk. Explicitly enabling encryption ensures data at rest is protected."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Added 'encrypted = true' to the first ebs_block_device block to ensure all EBS volumes defined in the AMI are encrypted at rest."
}
